from collections import deque

def solve(graph, start, end):
    """
    Returns the fewest directed edges from start to end in an adjacency dictionary.
    Missing keys have no outgoing edges. Returns -1 if unreachable.
    """
    if start == end:
        return 0

    # Initialize distances: all nodes are infinity, start node is 0
    distances = {node: float('inf') for node in graph}
    for node in graph:
        if node not in distances:
            distances[node] = float('inf')

    # Ensure start and end nodes are in the distance map even if they have no outgoing edges
    if start not in distances:
        distances[start] = float('inf')
    if end not in distances:
        distances[end] = float('inf')

    distances[start] = 0

    # Queue for BFS: stores (node, distance)
    queue = deque([(start, 0)])

    while queue:
        current_node, dist = queue.popleft()

        if current_node == end:
            return dist

        # Check for outgoing edges from current_node
        if current_node in graph:
            for neighbor in graph[current_node]:
                # If we found a shorter path (which BFS guarantees if we haven't visited)
                if distances[neighbor] == float('inf'):
                    distances[neighbor] = dist + 1
                    queue.append((neighbor, dist + 1))

    # If the queue is empty and we haven't reached the end
    return -1
